import sys


def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    n = int(input_data[0])

    records = []
    idx = 1
    for _ in range(n):
        tipo = input_data[idx]
        x = int(input_data[idx + 1])
        records.append((tipo, x))
        idx += 2

    current_time = 0
    first_event = True
    pending_time = None

    last_received = {}
    total_time = {}
    is_waiting = {}
    friends = set()

    for tipo, x in records:
        if tipo == "T":
            pending_time = x
        else:
            friends.add(x)
            if first_event:
                first_event = False
            else:
                if pending_time is not None:
                    current_time += pending_time
                    pending_time = None
                else:
                    current_time += 1

            if tipo == "R":
                last_received[x] = current_time
                is_waiting[x] = True
                if x not in total_time:
                    total_time[x] = 0
            elif tipo == "E":
                total_time[x] += current_time - last_received[x]
                is_waiting[x] = False

    for friend in sorted(friends):
        if is_waiting.get(friend, False):
            print(f"{friend} -1")
        else:
            print(f"{friend} {total_time[friend]}")


if __name__ == "__main__":
    solve()
